html:
{#- Shipment Manifest (Logistics): one load with the delivery notes and vehicles on board, signed by the driver at dispatch and by the receiver at delivery. A4, black on white. -#}
{%- macro esc(value) -%}{%- if value is defined and value is not none -%}{{ value|e }}{%- endif -%}{%- endmacro -%}
{%- macro num(value) -%}
{%- set n = frappe.utils.flt(value) -%}
{%- if n == frappe.utils.cint(n) -%}{{ frappe.utils.fmt_money(n, 0) }}{%- else -%}{{ frappe.format(n, {"fieldtype": "Float"}) }}{%- endif -%}
{%- endmacro -%}
{%- set booking = frappe.db.get_value("Transport Booking", doc.transport_booking, ["carrier_reference", "destination", "vehicle_type", "delivery_window_end"], as_dict=True) if doc.transport_booking else none -%}
{%- set notes = doc.items | map(attribute="delivery_note") | unique | list -%}
<style>
	@page { size: A4; margin: 15mm; }
	.hn-doc { color: #000; background: #fff; font-size: 9pt; line-height: 1.35; }
	.hn-doc table { width: 100%; border-collapse: collapse; }
	.hn-doc th, .hn-doc td { color: #000; background: #fff; border: 1px solid #000; padding: 1.2mm 1.8mm; text-align: left; vertical-align: top; }
	.hn-doc .hn-head { margin-bottom: 4mm; border-bottom: 0.6mm solid #000; }
	.hn-doc .hn-head td { border: 0; padding: 0 0 2mm 0; vertical-align: bottom; }
	.hn-doc .hn-company { font-size: 10pt; font-weight: bold; }
	.hn-doc .hn-title { font-size: 16pt; font-weight: bold; margin-top: 1mm; }
	.hn-doc .hn-right { text-align: right; }
	.hn-doc .hn-label { font-size: 7.5pt; }
	.hn-doc .hn-docno { font-size: 12pt; font-weight: bold; font-family: monospace; }
	.hn-doc .hn-state { display: inline-block; margin-top: 1mm; padding: 0.5mm 2mm; border: 0.5mm solid #000; font-weight: bold; }
	.hn-doc .hn-meta th { width: 18%; }
	.hn-doc .hn-meta td { width: 32%; }
	.hn-doc .hn-section { margin: 5mm 0 1.5mm 0; font-size: 10.5pt; font-weight: bold; }
	.hn-doc .hn-lines { margin-top: 4mm; }
	.hn-doc .hn-lines thead { display: table-header-group; }
	.hn-doc .hn-lines th { border-bottom: 0.5mm solid #000; }
	.hn-doc .hn-lines tr, .hn-doc .hn-sign, .hn-doc .hn-avoid { page-break-inside: avoid; break-inside: avoid; }
	.hn-doc .hn-num { text-align: right; white-space: nowrap; }
	.hn-doc .hn-strong { font-weight: bold; }
	.hn-doc .hn-mono { font-family: monospace; }
	.hn-doc .hn-summary { margin-top: 2mm; text-align: right; }
	.hn-doc .hn-sign { margin-top: 8mm; }
	.hn-doc .hn-sign td.hn-sign-cell { border: 0; padding: 0 3mm 0 0; width: 50%; }
	.hn-doc .hn-sign td.hn-sign-cell + td.hn-sign-cell { padding: 0 0 0 3mm; }
	.hn-doc .hn-sign-title { font-size: 10pt; font-weight: bold; margin-bottom: 1mm; }
	.hn-doc .hn-sign-box th { width: 32%; }
	.hn-doc .hn-sign-box td { height: 9mm; }
</style>
<div class="hn-doc">
	<table class="hn-head">
		<tr>
			<td>
				<div class="hn-company">{{ esc(doc.company) }}</div>
				<div class="hn-title">{{ _("Shipment Manifest") }}</div>
			</td>
			<td class="hn-right">
				<div class="hn-docno">{{ esc(doc.name) }}</div>
				{%- if doc.docstatus == 1 and doc.delivery_status %}<div>{{ _(doc.delivery_status) }}</div>{% endif %}
				{%- if doc.docstatus == 0 %}<div class="hn-state">{{ _("Draft") }}</div>{% endif %}
				{%- if doc.docstatus == 2 %}<div class="hn-state">{{ _("Cancelled") }}</div>{% endif %}
			</td>
		</tr>
	</table>
	<table class="hn-meta">
		<tr>
			<th>{{ _("Carrier") }}</th>
			<td>{{ esc(frappe.db.get_value("Supplier", doc.carrier, "supplier_name") or doc.carrier) }}</td>
			<th>{{ _("Transport Booking") }}</th>
			<td>{{ esc(doc.transport_booking) }}</td>
		</tr>
		<tr>
			<th>{{ _("Departure") }}</th>
			<td>{{ doc.get_formatted("departure") }}</td>
			<th>{{ _("Carrier Confirmation No") }}</th>
			<td>{{ esc(booking.carrier_reference) if booking else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Seal No") }}</th>
			<td class="hn-strong hn-mono">{{ esc(doc.seal_no) }}</td>
			<th>{{ _("Destination") }}</th>
			<td>{{ esc(booking.destination) if booking else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Truck / Unit No") }}</th>
			<td>{{ esc(doc.truck_plate) }}</td>
			<th>{{ _("Deliver By") }}</th>
			<td>{{ frappe.format(booking.delivery_window_end, {"fieldtype": "Datetime"}) if booking and booking.delivery_window_end else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Driver") }}</th>
			<td>{{ esc(doc.driver_name) }}</td>
			<th>{{ _("Equipment") }}</th>
			<td>{{ _(booking.vehicle_type) if booking and booking.vehicle_type else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Plant") }}</th>
			<td>{{ esc(frappe.db.get_value("Plant", doc.plant, "plant_name") or doc.plant) }}</td>
			<th>{{ _("Dispatched By") }}</th>
			<td>{{ esc(frappe.get_fullname(doc.dispatched_by)) if doc.dispatched_by else "" }}</td>
		</tr>
	</table>
	<table class="hn-lines">
		<thead>
			<tr>
				<th class="hn-num">#</th>
				<th>{{ _("Delivery Note") }}</th>
				<th>{{ _("Consignee") }}</th>
				<th>{{ _("Item") }}</th>
				<th>{{ _("VIN / Serial") }}</th>
				<th class="hn-num">{{ _("Qty") }}</th>
				<th>{{ _("Status") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in doc.items %}
			{%- set item_name = frappe.db.get_value("Item", row.item_code, "item_name") if row.item_code else none %}
			<tr>
				<td class="hn-num">{{ row.idx }}</td>
				<td>{{ esc(row.delivery_note) }}</td>
				<td>{{ esc(frappe.db.get_value("Customer", row.customer, "customer_name") or row.customer) if row.customer else "" }}</td>
				<td>{{ esc(row.item_code) }}{% if item_name and item_name != row.item_code %}<br>{{ esc(item_name) }}{% endif %}</td>
				<td class="hn-strong hn-mono">{{ esc(row.serial_no) }}</td>
				<td class="hn-num">{{ num(row.qty) }}</td>
				<td>{{ _(row.line_status) if row.line_status else "" }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>
	<div class="hn-summary">
		{{ _("Delivery Notes") }}: <span class="hn-strong">{{ notes | length }}</span>
		&nbsp;&nbsp;
		{{ _("Units") }}: <span class="hn-strong">{{ num(doc.items | sum(attribute="qty")) }}</span>
	</div>
	<table class="hn-sign">
		<tr>
			<td class="hn-sign-cell">
				<div class="hn-sign-title">{{ _("Driver") }}</div>
				<table class="hn-sign-box">
					<tr><th>{{ _("Name") }}</th><td>{{ esc(doc.driver_name) }}</td></tr>
					<tr><th>{{ _("Signature") }}</th><td></td></tr>
					<tr><th>{{ _("Date / Time") }}</th><td></td></tr>
				</table>
			</td>
			<td class="hn-sign-cell">
				<div class="hn-sign-title">{{ _("Receiver") }}</div>
				<table class="hn-sign-box">
					<tr><th>{{ _("Name") }}</th><td>{{ esc(doc.received_by_name) }}</td></tr>
					<tr><th>{{ _("Signature") }}</th><td></td></tr>
					<tr><th>{{ _("Date / Time") }}</th><td>{{ doc.get_formatted("delivered_at") if doc.delivered_at else "" }}</td></tr>
				</table>
			</td>
		</tr>
	</table>
</div>
